import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function EmotionRecommendPage({ movies = [] }) {
  const [selectedEmotion, setSelectedEmotion] = useState(null);
  const [recommendedMovie, setRecommendedMovie] = useState(null);
  const [loading, setLoading] = useState(false);

  const emotionOptions = [
    { id: 'comfort', label: '나는 오늘 위로가 필요해' },
    { id: 'laugh', label: '나는 오늘 웃음이 필요해' },
    { id: 'thrill', label: '나는 오늘 짜릿한 자극이 필요해' },
    { id: 'romance', label: '나는 오늘 설렘이 필요해' }
  ];

  const handleSelectEmotion = (option) => {
    setSelectedEmotion(option.label);
    setLoading(true);
    setRecommendedMovie(null);

    setTimeout(() => {
      let chosen = null;

      if (movies && movies.length > 0) {
        const randomIndex = Math.floor(Math.random() * movies.length);
        chosen = movies[randomIndex];
      }

      if (!chosen) {
        chosen = {
          title: '메가박스 시그니처 추천작',
          overview: '오늘 당신의 기분에 완벽하게 어울리는 감동적인 상영작입니다.',
          poster_path: null,
          backdrop_path: null
        };
      }

      setRecommendedMovie(chosen);
      setLoading(false);
    }, 500);
  };

  return (
    <div 
      className="w-full min-h-screen py-16 px-6 flex flex-col items-center justify-center relative bg-gradient-to-br from-purple-100 to-white" 
      style={{ fontFamily: 'Pretendard, sans-serif' }}
    >
      <div className="w-full max-w-3xl relative overflow-hidden bg-white/40 backdrop-blur-2xl border border-white/60 shadow-[0_8px_32px_0_rgba(80,51,150,0.08)] rounded-[40px] p-8 md:p-12 space-y-10">
        
        {/* 상단 반사광 효과 */}
        <div className="absolute top-0 left-0 w-full h-32 bg-gradient-to-b from-white/40 to-transparent pointer-events-none"></div>

        {/* 상단 타이틀 영역 */}
        <div className="text-center space-y-4 relative z-10">
          <span className="inline-block text-[11px] font-black tracking-widest text-[#503396] uppercase bg-white/60 backdrop-blur-md px-4 py-1.5 rounded-full border border-white shadow-sm">
            MEGABOX EMOTION CARE
          </span>
          <h2 className="text-3xl md:text-4xl font-black text-zinc-900 tracking-tight">
            오늘의 감정에 맞는 영화를 골라드려요
          </h2>
          {/* 💡 수정된 부분: 더 따뜻하고 감성적인 서브 카피로 변경 */}
          <p className="text-xs text-zinc-600 font-medium">
            오늘 당신의 마음을 들려주세요. 당신의 감정을 따뜻하게 보살펴 줄 영화를 추천해 드릴게요.
          </p>
        </div>

        {/* 투명한 유리 질감의 선택 버튼 */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 relative z-10">
          {emotionOptions.map((option) => (
            <button
              key={option.id}
              onClick={() => handleSelectEmotion(option)}
              className={`p-5 rounded-2xl text-center font-black text-sm transition-all duration-300 backdrop-blur-xl border ${
                selectedEmotion === option.label
                  ? 'bg-[#503396]/70 text-white border-white/40 shadow-[0_8px_20px_rgba(80,51,150,0.25)] scale-[1.02]' 
                  : 'bg-white/30 hover:bg-white/50 text-zinc-700 border-white/50 shadow-sm hover:shadow-md'
              }`}
            >
              {option.label}
            </button>
          ))}
        </div>

        {/* 로딩 상태 */}
        {loading && (
          <div className="text-center py-12 text-[#503396] font-bold animate-pulse text-sm">
            마음에 쏙 드는 영화를 찾는 중입니다...
          </div>
        )}

        {/* 추천 결과 카드 */}
        {recommendedMovie && !loading && (
          <div className="bg-white/50 backdrop-blur-xl border border-white/60 rounded-3xl p-8 shadow-xl flex flex-col md:flex-row items-center gap-8 animate-fade-in relative z-10">
            
            {/* 포스터 영역 */}
            <div className="w-44 h-60 rounded-2xl bg-zinc-100 overflow-hidden shadow-lg shrink-0 border border-white flex items-center justify-center relative">
              {recommendedMovie.poster_path || recommendedMovie.backdrop_path ? (
                <img 
                  src={`https://image.tmdb.org/t/p/w500${recommendedMovie.poster_path || recommendedMovie.backdrop_path}`} 
                  alt={recommendedMovie.title} 
                  className="w-full h-full object-cover" 
                />
              ) : (
                <span className="text-xs text-zinc-400 font-bold">MEGABOX MOVIE</span>
              )}
            </div>

            {/* 컨텐츠 및 설명 영역 */}
            <div className="flex flex-col justify-center space-y-4 text-left w-full">
              <div>
                <span className="text-[11px] font-black text-[#503396] bg-white/60 backdrop-blur-md px-3 py-1 rounded-full border border-white shadow-sm">
                  {selectedEmotion}
                </span>
                <h3 className="text-2xl md:text-3xl font-black text-zinc-900 mt-3 mb-2 drop-shadow-sm">
                  {recommendedMovie.title}
                </h3>
                <p className="text-xs text-zinc-600 leading-relaxed font-medium line-clamp-3">
                  {recommendedMovie.overview || "일상에 특별한 감동과 여운을 선사할 추천 상영작입니다."}
                </p>
              </div>

              {/* 하단 액션 버튼 */}
              <div className="flex gap-3 pt-2">
                <Link 
                  to="/schedule" 
                  className="flex-grow text-center py-3.5 bg-[#503396]/80 hover:bg-[#503396] text-white font-black text-xs rounded-xl transition shadow-md backdrop-blur-md border border-white/20"
                >
                  상영시간표 및 예매하기
                </Link>
                <button 
                  onClick={() => { setSelectedEmotion(null); setRecommendedMovie(null); }} 
                  className="px-5 py-3.5 bg-white/40 hover:bg-white/60 text-zinc-700 font-black text-xs rounded-xl transition shadow-sm backdrop-blur-md border border-white/50"
                >
                  다시 고르기
                </button>
              </div>
            </div>

          </div>
        )}
      </div>
    </div>
  );
}

export default EmotionRecommendPage;
